//! Team plans: the orchestrator's structured breakdown of a request into agents. A plan is
//! generated by `claude -p` with a JSON schema, validated here, and must be approved by the user
//! before any agent session is spawned.

use std::collections::{HashMap, HashSet};
use std::sync::Mutex;
use std::time::Duration;

use serde::{Deserialize, Serialize};

use crate::store::{Store, StoreError, TeamRow};
use crate::worktree::Worktree;

/// One session is reserved for the orchestrator; the rest stay under `policy::MAX_SESSIONS`.
pub const MAX_AGENTS: usize = 8;
pub const MAX_REQUEST_LEN: usize = 8 * 1024;
const MAX_FIELD_LEN: usize = 4 * 1024;
const PLANNER_TIMEOUT: Duration = Duration::from_secs(300);
pub const ORCHESTRATOR_ID: &str = "orchestrator";

#[derive(Debug, thiserror::Error)]
pub enum PlanError {
    #[error("invalid plan: {0}")]
    Invalid(String),
    #[error("planner failed: {0}")]
    Planner(String),
    #[error("plan not found")]
    NotFound,
    #[error("plan has not been approved")]
    NotApproved,
    #[error("plan was already approved")]
    AlreadyApproved,
    #[error("team was closed")]
    Closed,
    #[error("team store: {0}")]
    Store(String),
    #[error("agent not found in plan: {0}")]
    UnknownAgent(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    Parallel,
    Sequential,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AgentSpec {
    pub id: String,
    pub name: String,
    pub role: String,
    pub scope: String,
    pub task: String,
    pub acceptance: Vec<String>,
    #[serde(default)]
    pub depends_on: Vec<String>,
    /// Commands that check the acceptance criteria; run in the agent's worktree after it
    /// reports done. Approved together with the plan.
    #[serde(default)]
    pub verify: Vec<Check>,
    /// CLI that runs this agent; chosen by the user before approval (the planner never sets it).
    #[serde(default)]
    pub cli: AgentCli,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AgentCli {
    #[default]
    Claude,
    Codex,
}

impl AgentCli {
    pub fn program(self) -> crate::policy::Program {
        use crate::policy::Program;
        match self {
            Self::Claude => Program::Claude,
            Self::Codex => Program::Codex,
        }
    }
}

pub const MAX_CHECKS: usize = 4;
const MAX_CHECK_ARGS: usize = 16;
const MAX_CHECK_ARG_LEN: usize = 200;

/// Programs a verification command may use (`.cmd` shims such as npm are not allowed).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CheckProgram {
    Cargo,
    Node,
    Python,
    Pytest,
}

impl CheckProgram {
    pub fn program(self) -> crate::policy::Program {
        use crate::policy::Program;
        match self {
            Self::Cargo => Program::Cargo,
            Self::Node => Program::Node,
            Self::Python => Program::Python,
            Self::Pytest => Program::Pytest,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Self::Cargo => "cargo",
            Self::Node => "node",
            Self::Python => "python",
            Self::Pytest => "pytest",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Check {
    pub program: CheckProgram,
    #[serde(default)]
    pub args: Vec<String>,
}

impl Check {
    /// Display form, e.g. `pytest test_x.py`.
    pub fn display(&self) -> String {
        std::iter::once(self.program.name())
            .chain(self.args.iter().map(String::as_str))
            .collect::<Vec<_>>()
            .join(" ")
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Plan {
    pub summary: String,
    pub mode: Mode,
    pub agents: Vec<AgentSpec>,
}

/// JSON schema handed to `claude --json-schema`. Must match `Plan` (camelCase).
pub const PLAN_SCHEMA: &str = r#"{"type":"object","additionalProperties":false,"required":["summary","mode","agents"],"properties":{"summary":{"type":"string"},"mode":{"type":"string","enum":["parallel","sequential"]},"agents":{"type":"array","minItems":1,"maxItems":8,"items":{"type":"object","additionalProperties":false,"required":["id","name","role","scope","task","acceptance","dependsOn","verify"],"properties":{"id":{"type":"string","pattern":"^[a-z0-9][a-z0-9-]{0,31}$"},"name":{"type":"string"},"role":{"type":"string"},"scope":{"type":"string"},"task":{"type":"string"},"acceptance":{"type":"array","items":{"type":"string"}},"dependsOn":{"type":"array","items":{"type":"string"}},"verify":{"type":"array","maxItems":4,"items":{"type":"object","additionalProperties":false,"required":["program","args"],"properties":{"program":{"type":"string","enum":["cargo","node","python","pytest"]},"args":{"type":"array","maxItems":16,"items":{"type":"string"}}}}}}}}}}"#;

fn valid_agent_id(id: &str) -> bool {
    let b = id.as_bytes();
    !b.is_empty()
        && b.len() <= 32
        && (b[0].is_ascii_lowercase() || b[0].is_ascii_digit())
        && b.iter()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'-')
        && id != ORCHESTRATOR_ID
}

impl Plan {
    pub fn validate(&self) -> Result<(), PlanError> {
        let bad = |m: String| Err(PlanError::Invalid(m));
        if self.agents.is_empty() || self.agents.len() > MAX_AGENTS {
            return bad(format!("agent count must be 1..={MAX_AGENTS}"));
        }
        if self.summary.len() > MAX_FIELD_LEN {
            return bad("summary too long".into());
        }
        let mut ids = HashSet::new();
        for a in &self.agents {
            if !valid_agent_id(&a.id) {
                return bad(format!("bad agent id {:?}", a.id));
            }
            if !ids.insert(a.id.as_str()) {
                return bad(format!("duplicate agent id {}", a.id));
            }
            let fields = [&a.name, &a.role, &a.scope, &a.task];
            if fields
                .iter()
                .any(|f| f.trim().is_empty() || f.len() > MAX_FIELD_LEN)
                || a.acceptance.iter().any(|c| c.len() > MAX_FIELD_LEN)
                || a.acceptance.len() > 32
            {
                return bad(format!("agent {} has empty or oversized fields", a.id));
            }
            let bad_check = a.verify.len() > MAX_CHECKS
                || a.verify.iter().any(|c| {
                    c.args.len() > MAX_CHECK_ARGS
                        || c.args
                            .iter()
                            .any(|x| x.len() > MAX_CHECK_ARG_LEN || x.contains('\0'))
                });
            if bad_check {
                return bad(format!("agent {} has invalid verification commands", a.id));
            }
        }
        for a in &self.agents {
            for d in &a.depends_on {
                if d == &a.id || !ids.contains(d.as_str()) {
                    return bad(format!("agent {} has bad dependency {d:?}", a.id));
                }
            }
        }
        if self.has_cycle() {
            return bad("dependency cycle".into());
        }
        Ok(())
    }

    /// Agents that must be done before `id` may start: its dependencies, and in sequential
    /// mode every agent before it in dependency order. Assumes `validate` passed.
    pub fn prerequisites(&self, id: &str) -> Vec<&str> {
        match self.mode {
            Mode::Parallel => self
                .agents
                .iter()
                .find(|a| a.id == id)
                .map(|a| a.depends_on.iter().map(String::as_str).collect())
                .unwrap_or_default(),
            Mode::Sequential => self
                .topo_order()
                .into_iter()
                .map(|a| a.id.as_str())
                .take_while(|a| *a != id)
                .collect(),
        }
    }

    /// Agents in dependency order (plan order among those ready). Assumes `validate` passed.
    pub fn topo_order(&self) -> Vec<&AgentSpec> {
        let mut done: HashSet<&str> = HashSet::new();
        let mut out = Vec::new();
        while out.len() < self.agents.len() {
            let next = self.agents.iter().find(|a| {
                !done.contains(a.id.as_str())
                    && a.depends_on.iter().all(|d| done.contains(d.as_str()))
            });
            let Some(a) = next else { break }; // cycle: validate() rejects these
            done.insert(&a.id);
            out.push(a);
        }
        out
    }

    fn has_cycle(&self) -> bool {
        // Kahn's algorithm: a cycle leaves nodes with unresolved in-degree.
        let mut indeg: HashMap<&str, usize> = self
            .agents
            .iter()
            .map(|a| {
                let unique: HashSet<&str> = a.depends_on.iter().map(String::as_str).collect();
                (a.id.as_str(), unique.len())
            })
            .collect();
        let mut ready: Vec<&str> = indeg
            .iter()
            .filter(|(_, n)| **n == 0)
            .map(|(id, _)| *id)
            .collect();
        let mut done = 0;
        while let Some(id) = ready.pop() {
            done += 1;
            for a in &self.agents {
                if a.depends_on.iter().any(|d| d == id) {
                    let n = indeg.get_mut(a.id.as_str()).expect("known id");
                    *n -= 1;
                    if *n == 0 {
                        ready.push(&a.id);
                    }
                }
            }
        }
        done != self.agents.len()
    }

    pub fn agent(&self, id: &str) -> Result<&AgentSpec, PlanError> {
        self.agents
            .iter()
            .find(|a| a.id == id)
            .ok_or_else(|| PlanError::UnknownAgent(id.into()))
    }
}

pub fn planner_prompt(request: &str) -> String {
    format!(
        "You are the INA orchestrator planner. Break the user's request into a small team of \
         AI coding agents (1 to {MAX_AGENTS}). For each agent give a short kebab-case id, a name, \
         a role, the scope (files/areas it owns, non-overlapping where possible), the concrete \
         task, verifiable acceptance criteria, dependsOn (ids it must wait for), and verify: up \
         to {MAX_CHECKS} commands that check the criteria automatically, using only the programs \
         cargo, node, python or pytest (e.g. {{\"program\": \"pytest\", \"args\": [\"test_x.py\"]}}); \
         they run in the agent's worktree, so use [] when nothing can be checked. Choose mode \
         \"parallel\" when agents can work at the same time, otherwise \"sequential\". Do not \
         modify any files; only return the plan.\n\nUser request:\n{request}"
    )
}

pub fn orchestrator_prompt(plan: &Plan, worktrees: &HashMap<String, Worktree>) -> String {
    let team: Vec<String> = plan
        .agents
        .iter()
        .map(|a| {
            let (branch, path) = worktrees
                .get(&a.id)
                .map(|w| (w.branch.clone(), w.path.display().to_string()))
                .unwrap_or_default();
            format!(
                "- {} ({}): {} [depends on: {}] branch `{}`, worktree {}",
                a.id,
                a.role,
                a.task,
                a.depends_on.join(", "),
                branch,
                path
            )
        })
        .collect();
    format!(
        "You are the INA orchestrator. The user approved this plan ({:?} mode): {}\n\nTeam:\n{}\n\n\
         Each agent runs in its own terminal and commits to its own branch in its own git \
         worktree; their changes do not appear in your checkout until integrated. Monitor the \
         branches read-only (e.g. `git log HEAD..<branch>`, `git diff HEAD...<branch>`), \
         validate results against the acceptance criteria, and report honestly whether the team \
         is ready to integrate. Each agent reports in `<worktree>/.ina/result.json`; every status \
         change is appended to `.ina/events.jsonl` in this directory. To instruct an agent, \
         write a JSON file to `.ina/outbox/<name>.json` in this directory: {{\"type\": \
         \"instruction\", \"to\": \"<agent id>\", \"text\": \"...\"}}; the user approves it in INA \
         before it is delivered. Write no other files. Never merge, rebase, reset or commit \
         yourself: the user integrates through INA after reviewing. Do not do the agents' work \
         yourself.",
        plan.mode,
        plan.summary,
        team.join("\n")
    )
}

pub fn agent_prompt(plan: &Plan, agent: &AgentSpec, branch: &str) -> String {
    let criteria: Vec<String> = agent.acceptance.iter().map(|c| format!("- {c}")).collect();
    format!(
        "You are agent \"{}\" ({}) in an INA team. Overall goal: {}\n\nYour scope: {}\n\
         Your task: {}\n\nAcceptance criteria:\n{}\n\nDepends on: {}. You work in your own git \
         worktree on branch `{}`; commit your work there and do not touch other branches. Stay \
         within your scope. Your assignment is also in `.ina/task.json`. When you finish, fail or \
         are blocked, write `.ina/result.json` as JSON: {{\"status\": \"done\" | \"failed\" | \
         \"blocked\", \"summary\": \"...\", \"files\": [\"changed paths\"], \"notes\": \
         \"optional\"}}; INA reads it to track your status. Never report done unless the criteria \
         are met. To ask the user something, report progress or hand off to another agent, write \
         `.ina/outbox/<name>.json`: {{\"type\": \"question\" | \"progress\" | \"blocked\" | \
         \"handoff\", \"text\": \"...\", \"to\": \"<agent id, optional>\"}}. Answers and \
         instructions arrive in `.ina/inbox/`; when INA tells you about a new message, read it. If `.ina/task.json` has `previousAttempt`, an earlier run ended that way: fix that first.",
        agent.name,
        agent.role,
        plan.summary,
        agent.scope,
        agent.task,
        criteria.join("\n"),
        if agent.depends_on.is_empty() {
            "none".into()
        } else {
            agent.depends_on.join(", ")
        },
        branch
    )
}

/// Tools the orchestrator may not use: it reviews, the user integrates through INA.
const ORCHESTRATOR_DENIED: &[&str] = &[
    // No file edits except `.ina/outbox/` (pre-allowed below; verified with `claude -p` that
    // the specific allow wins over this bare deny). Path denies are kept as defense in depth.
    "Edit",
    "NotebookEdit",
    "Edit(.ina/worktrees/**)",
    "Edit(.git/**)",
    "Edit(.ina/events.jsonl)",
];

/// Git commands the orchestrator may not run. Denied for both shell tools: on Windows
/// Claude Code also has a PowerShell tool (verified with `claude -p` that its rules apply).
const ORCHESTRATOR_DENIED_GIT: &[&str] = &[
    "merge",
    "rebase",
    "reset",
    "commit",
    "push",
    "cherry-pick",
    "checkout",
    "switch",
    "restore",
    "stash",
    "worktree",
    "update-ref",
    "branch -f",
    "branch -D",
    // Global options put the subcommand out of reach of the prefix rules above.
    "-C",
    "-c",
];

/// Prompt first: `--disallowedTools` is variadic and would swallow a trailing prompt.
pub fn orchestrator_args(prompt: String) -> Vec<String> {
    let mut args = vec![
        prompt,
        "--permission-mode".to_string(),
        "default".to_string(),
        "--allowedTools".to_string(),
        "Edit(.ina/outbox/**)".to_string(),
        "--disallowedTools".to_string(),
    ];
    args.extend(ORCHESTRATOR_DENIED.iter().map(|s| s.to_string()));
    for tool in ["Bash", "PowerShell"] {
        args.extend(
            ORCHESTRATOR_DENIED_GIT
                .iter()
                .map(|cmd| format!("{tool}(git {cmd}:*)")),
        );
    }
    args
}

/// Args for the non-interactive planner run. No tools, no MCP: it can only answer.
pub fn planner_args(request: &str) -> Vec<String> {
    [
        "-p",
        &planner_prompt(request),
        "--output-format",
        "json",
        "--json-schema",
        PLAN_SCHEMA,
        "--tools",
        "",
        "--strict-mcp-config",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect()
}

/// Extract and validate the plan from `claude -p --output-format json` stdout.
pub fn parse_planner_output(stdout: &str) -> Result<Plan, PlanError> {
    #[derive(Deserialize)]
    struct Envelope {
        #[serde(default)]
        is_error: bool,
        #[serde(default)]
        result: Option<String>,
        structured_output: Option<Plan>,
    }
    let env: Envelope = serde_json::from_str(stdout.trim())
        .map_err(|e| PlanError::Planner(format!("unparseable output: {e}")))?;
    if env.is_error {
        return Err(PlanError::Planner(
            env.result.unwrap_or_else(|| "unknown error".into()),
        ));
    }
    let plan = env
        .structured_output
        .ok_or_else(|| PlanError::Planner("no structured output".into()))?;
    plan.validate()?;
    Ok(plan)
}

/// Run the planner to completion (blocking) with a timeout. `program` comes from the policy.
pub fn run_planner(spec: &crate::pty::SpawnSpec) -> Result<Plan, PlanError> {
    let fail = |m: String| PlanError::Planner(m);
    let mut child = crate::pty::piped_command(spec)
        .spawn()
        .map_err(|e| fail(format!("spawn: {e}")))?;
    let (status, output) =
        crate::pty::wait_output(&mut child, PLANNER_TIMEOUT).map_err(|e| fail(e.to_string()))?;
    let status = status.ok_or_else(|| fail("timed out".into()))?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    if !status.success() && stdout.trim().is_empty() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let tail = crate::pty::tail(&stderr, 500);
        return Err(fail(format!("exit {:?}: {tail}", status.code())));
    }
    parse_planner_output(&stdout)
}

/// An approved plan, ready to spawn.
#[derive(Debug, Clone)]
pub struct Team {
    pub id: u64,
    pub workspace_id: i64,
    pub plan: Plan,
    pub worktrees: HashMap<String, Worktree>,
}

fn db_err(e: StoreError) -> PlanError {
    match e {
        StoreError::TeamNotFound(_) => PlanError::NotFound,
        StoreError::TeamAlreadyApproved(_) => PlanError::AlreadyApproved,
        e => PlanError::Store(e.to_string()),
    }
}

fn json_err(e: serde_json::Error) -> PlanError {
    PlanError::Store(format!("corrupt team record: {e}"))
}

fn to_id(id: u64) -> Result<i64, PlanError> {
    i64::try_from(id).map_err(|_| PlanError::NotFound)
}

/// Workspace id, plan, and worktrees (if approved).
type Decoded = (i64, Plan, Option<HashMap<String, Worktree>>);

fn decode(row: TeamRow) -> Result<Decoded, PlanError> {
    let plan = serde_json::from_str(&row.plan).map_err(json_err)?;
    let worktrees = row
        .worktrees
        .map(|w| serde_json::from_str(&w))
        .transpose()
        .map_err(json_err)?;
    Ok((row.workspace_id, plan, worktrees))
}

/// Marks a team as being cleaned up while alive (see [`PlanStore::cleaning`]).
pub struct CleaningGuard<'a> {
    plans: &'a PlanStore,
    id: u64,
}

impl Drop for CleaningGuard<'_> {
    fn drop(&mut self) {
        if let Ok(mut c) = self.plans.cleaning.lock() {
            c.remove(&self.id);
        }
    }
}

/// Team plans, persisted in SQLite so a team survives restarts (agent prompts are always
/// rebuilt from here, never taken from the frontend), plus the live sessions of each team.
#[derive(Default)]
pub struct PlanStore {
    /// team -> (session id, agent id)
    sessions: Mutex<HashMap<u64, Vec<(String, String)>>>,
    /// Decoded approved teams; a team's row never changes after approval until it is closed.
    approved: Mutex<HashMap<u64, Team>>,
    /// Teams whose worktrees are being removed: the background tick leaves them alone.
    cleaning: Mutex<std::collections::HashSet<u64>>,
}

impl PlanStore {
    /// Mark `id` as being cleaned up until the returned guard drops.
    pub fn cleaning(&self, id: u64) -> CleaningGuard<'_> {
        if let Ok(mut c) = self.cleaning.lock() {
            c.insert(id);
        }
        CleaningGuard { plans: self, id }
    }

    pub fn is_cleaning(&self, id: u64) -> bool {
        self.cleaning.lock().is_ok_and(|c| c.contains(&id))
    }

    /// Drop cached teams of a removed workspace (its rows are deleted in cascade).
    pub fn forget_workspace(&self, workspace_id: i64) {
        if let Ok(mut cache) = self.approved.lock() {
            cache.retain(|_, t| t.workspace_id != workspace_id);
        }
    }

    pub fn insert(&self, db: &Store, workspace_id: i64, plan: &Plan) -> Result<u64, PlanError> {
        let json = serde_json::to_string(plan).map_err(json_err)?;
        let id = db.insert_team(workspace_id, &json).map_err(db_err)?;
        u64::try_from(id).map_err(|_| PlanError::NotFound)
    }

    /// Apply the user's CLI choices to a pending plan; unknown agent ids are rejected.
    pub fn set_clis(
        &self,
        db: &Store,
        id: u64,
        clis: &HashMap<String, AgentCli>,
    ) -> Result<Plan, PlanError> {
        let (_, mut plan) = self.pending(db, id)?;
        if clis.keys().any(|k| plan.agents.iter().all(|a| &a.id != k)) {
            return Err(PlanError::NotFound);
        }
        for a in &mut plan.agents {
            if let Some(cli) = clis.get(&a.id) {
                a.cli = *cli;
            }
        }
        let json = serde_json::to_string(&plan).map_err(json_err)?;
        db.set_pending_plan(to_id(id)?, &json).map_err(db_err)?;
        Ok(plan)
    }

    /// A plan still awaiting approval.
    pub fn pending(&self, db: &Store, id: u64) -> Result<(i64, Plan), PlanError> {
        let (workspace_id, plan, worktrees) = decode(db.get_team(to_id(id)?).map_err(db_err)?)?;
        if worktrees.is_some() {
            return Err(PlanError::AlreadyApproved);
        }
        Ok((workspace_id, plan))
    }

    /// Record approval with every agent's worktree. Fails if already approved.
    pub fn approve(
        &self,
        db: &Store,
        id: u64,
        worktrees: &HashMap<String, Worktree>,
    ) -> Result<(), PlanError> {
        let json = serde_json::to_string(worktrees).map_err(json_err)?;
        db.approve_team(to_id(id)?, &json).map_err(db_err)
    }

    pub fn approved(&self, db: &Store, id: u64) -> Result<Team, PlanError> {
        // Held across the miss so a concurrent `close` cannot be undone by a stale insert.
        let mut cache = self
            .approved
            .lock()
            .map_err(|e| PlanError::Store(e.to_string()))?;
        if let Some(team) = cache.get(&id) {
            return Ok(team.clone());
        }
        let row = db.get_team(to_id(id)?).map_err(db_err)?;
        if row.closed {
            return Err(PlanError::Closed);
        }
        let (workspace_id, plan, worktrees) = decode(row)?;
        let team = Team {
            id,
            workspace_id,
            plan,
            worktrees: worktrees.ok_or(PlanError::NotApproved)?,
        };
        cache.insert(id, team.clone());
        Ok(team)
    }

    /// The plan to show again for review after the window reloaded, if any (`Store::latest_draft`).
    pub fn latest_draft(
        &self,
        db: &Store,
        workspace_id: i64,
    ) -> Result<Option<(u64, Plan)>, PlanError> {
        db.latest_draft(workspace_id)
            .map_err(db_err)?
            .map(|row| {
                let id = u64::try_from(row.id).map_err(|_| PlanError::NotFound)?;
                let (_, plan, _) = decode(row)?;
                Ok((id, plan))
            })
            .transpose()
    }

    /// Approved, open teams of a workspace (newest first).
    pub fn open_teams(&self, db: &Store, workspace_id: i64) -> Result<Vec<Team>, PlanError> {
        db.open_teams(workspace_id)
            .map_err(db_err)?
            .into_iter()
            .map(|row| {
                let id = u64::try_from(row.id).map_err(|_| PlanError::NotFound)?;
                let (workspace_id, plan, worktrees) = decode(row)?;
                Ok(Team {
                    id,
                    workspace_id,
                    plan,
                    worktrees: worktrees.unwrap_or_default(),
                })
            })
            .collect()
    }

    pub fn close(&self, db: &Store, id: u64) -> Result<(), PlanError> {
        let mut cache = self
            .approved
            .lock()
            .map_err(|e| PlanError::Store(e.to_string()))?;
        db.close_team(to_id(id)?).map_err(db_err)?;
        cache.remove(&id);
        Ok(())
    }

    pub fn add_session(&self, team: u64, session: &str, agent: &str) {
        let mut g = self.sessions.lock().expect("session map poisoned");
        g.entry(team)
            .or_default()
            .push((session.to_owned(), agent.to_owned()));
    }

    /// Take (and forget) the sessions spawned for a team.
    pub fn take_sessions(&self, team: u64) -> Vec<String> {
        let mut g = self.sessions.lock().expect("session map poisoned");
        g.remove(&team)
            .unwrap_or_default()
            .into_iter()
            .map(|(s, _)| s)
            .collect()
    }

    /// Sessions spawned for one agent of a team.
    pub fn agent_sessions(&self, team: u64, agent: &str) -> Vec<String> {
        let g = self.sessions.lock().expect("session map poisoned");
        g.get(&team)
            .map(|l| {
                l.iter()
                    .filter(|(_, a)| a == agent)
                    .map(|(s, _)| s.clone())
                    .collect()
            })
            .unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn orchestrator_denies_git_writes_in_both_shells() {
        let args = orchestrator_args("p".into());
        for rule in [
            "Bash(git commit:*)",
            "PowerShell(git commit:*)",
            "PowerShell(git -C:*)",
            "Bash(git worktree:*)",
        ] {
            assert!(args.iter().any(|a| a == rule), "missing {rule}");
        }
        assert_eq!(args[0], "p");
    }

    fn agent(id: &str, deps: &[&str]) -> AgentSpec {
        AgentSpec {
            id: id.into(),
            name: id.into(),
            role: "dev".into(),
            scope: "src".into(),
            task: "do it".into(),
            acceptance: vec!["tests pass".into()],
            depends_on: deps.iter().map(|d| d.to_string()).collect(),
            verify: vec![],
            cli: AgentCli::Claude,
        }
    }

    fn plan(agents: Vec<AgentSpec>) -> Plan {
        Plan {
            summary: "goal".into(),
            mode: Mode::Parallel,
            agents,
        }
    }

    #[test]
    fn topo_order_respects_dependencies() {
        let p = plan(vec![
            agent("ui", &["api"]),
            agent("docs", &[]),
            agent("api", &[]),
        ]);
        let ids: Vec<_> = p.topo_order().iter().map(|a| a.id.as_str()).collect();
        assert_eq!(ids, ["docs", "api", "ui"]);
    }

    #[test]
    fn verification_commands_are_bounded() {
        let mut a = agent("api", &[]);
        a.verify = vec![Check {
            program: CheckProgram::Pytest,
            args: vec!["test_api.py".into()],
        }];
        assert_eq!(a.verify[0].display(), "pytest test_api.py");
        plan(vec![a.clone()]).validate().unwrap();
        a.verify = vec![a.verify[0].clone(); MAX_CHECKS + 1];
        assert!(plan(vec![a.clone()]).validate().is_err());
        a.verify = vec![Check {
            program: CheckProgram::Node,
            args: vec!["x\0y".into()],
        }];
        assert!(plan(vec![a]).validate().is_err());
        // npm (a .cmd shim) is not a valid program.
        assert!(serde_json::from_str::<Check>(r#"{"program":"npm","args":["test"]}"#).is_err());
    }

    #[test]
    fn duplicate_dependency_is_not_a_cycle() {
        plan(vec![agent("api", &[]), agent("ui", &["api", "api"])])
            .validate()
            .unwrap();
    }

    #[test]
    fn prerequisites_follow_mode() {
        let mut p = plan(vec![
            agent("ui", &["api"]),
            agent("docs", &[]),
            agent("api", &[]),
        ]);
        assert_eq!(p.prerequisites("ui"), ["api"]);
        assert!(p.prerequisites("docs").is_empty());
        p.mode = Mode::Sequential;
        assert!(p.prerequisites("docs").is_empty());
        assert_eq!(p.prerequisites("api"), ["docs"]);
        assert_eq!(p.prerequisites("ui"), ["docs", "api"]);
    }

    #[test]
    fn accepts_valid_plan() {
        plan(vec![agent("api", &[]), agent("ui", &["api"])])
            .validate()
            .unwrap();
    }

    #[test]
    fn rejects_bad_plans() {
        let cases = [
            plan(vec![]),
            plan((0..9).map(|i| agent(&format!("a{i}"), &[])).collect()),
            plan(vec![agent("Bad Id", &[])]),
            plan(vec![agent("orchestrator", &[])]),
            plan(vec![agent("a", &[]), agent("a", &[])]),
            plan(vec![agent("a", &["missing"])]),
            plan(vec![agent("a", &["a"])]),
            plan(vec![agent("a", &["b"]), agent("b", &["a"])]),
        ];
        for p in cases {
            assert!(p.validate().is_err(), "{p:?}");
        }
    }

    #[test]
    fn parses_planner_envelope() {
        let p = plan(vec![agent("api", &[])]);
        let out = serde_json::json!({ "is_error": false, "result": "x", "structured_output": p });
        assert_eq!(parse_planner_output(&out.to_string()).unwrap(), p);

        let err = r#"{"is_error":true,"result":"auth required"}"#;
        assert!(
            matches!(parse_planner_output(err), Err(PlanError::Planner(m)) if m == "auth required")
        );
        assert!(parse_planner_output("not json").is_err());
        assert!(parse_planner_output(r#"{"is_error":false}"#).is_err());
    }

    #[test]
    fn cli_choice_applies_only_before_approval() {
        let db = Store::in_memory().unwrap();
        let ws = db.add_workspace(&std::env::temp_dir()).unwrap();
        let store = PlanStore::default();
        let p = plan(vec![agent("api", &[]), agent("ui", &[])]);
        let id = store.insert(&db, ws.id, &p).unwrap();
        let unknown = HashMap::from([("nope".to_string(), AgentCli::Codex)]);
        assert!(store.set_clis(&db, id, &unknown).is_err());
        let clis = HashMap::from([("ui".to_string(), AgentCli::Codex)]);
        store.set_clis(&db, id, &clis).unwrap();
        let (_, saved) = store.pending(&db, id).unwrap();
        assert_eq!(saved.agents[0].cli, AgentCli::Claude);
        assert_eq!(saved.agents[1].cli, AgentCli::Codex);
        store.approve(&db, id, &HashMap::new()).unwrap();
        assert!(matches!(
            store.set_clis(&db, id, &clis),
            Err(PlanError::AlreadyApproved)
        ));
    }

    #[test]
    fn spawning_requires_approval() {
        let db = Store::in_memory().unwrap();
        let dir = std::env::temp_dir();
        let ws = db.add_workspace(&dir).unwrap();
        let store = PlanStore::default();
        let id = store
            .insert(&db, ws.id, &plan(vec![agent("api", &[])]))
            .unwrap();
        assert!(matches!(
            store.approved(&db, id),
            Err(PlanError::NotApproved)
        ));
        assert_eq!(store.pending(&db, id).unwrap().0, ws.id);
        let wt = Worktree {
            path: "C:/w/.ina/worktrees/r-api".into(),
            branch: "ina/r/api".into(),
        };
        let map = HashMap::from([("api".to_string(), wt.clone())]);
        store.approve(&db, id, &map).unwrap();
        let team = store.approved(&db, id).unwrap();
        assert_eq!((team.workspace_id, &team.worktrees["api"]), (ws.id, &wt));
        assert!(matches!(
            store.pending(&db, id),
            Err(PlanError::AlreadyApproved)
        ));
        assert!(matches!(
            store.approve(&db, id, &map),
            Err(PlanError::AlreadyApproved)
        ));
        assert!(matches!(
            store.approved(&db, id + 1),
            Err(PlanError::NotFound)
        ));
        assert_eq!(store.open_teams(&db, ws.id).unwrap().len(), 1);
        store.close(&db, id).unwrap();
        assert!(
            matches!(store.approved(&db, id), Err(PlanError::Closed)),
            "closing drops the cached team"
        );

        store.add_session(id, "s-1", "api");
        assert_eq!(store.agent_sessions(id, "api"), ["s-1"]);
        assert_eq!(store.take_sessions(id), ["s-1"]);
        assert!(store.take_sessions(id).is_empty());

        store.close(&db, id).unwrap();
        assert!(matches!(store.approved(&db, id), Err(PlanError::Closed)));
        assert!(store.open_teams(&db, ws.id).unwrap().is_empty());
    }

    #[test]
    fn prompts_carry_plan_data() {
        let p = plan(vec![agent("api", &[]), agent("ui", &["api"])]);
        let a = agent_prompt(&p, p.agent("ui").unwrap(), "ina/r/ui");
        assert!(a.contains("Depends on: api") && a.contains("- tests pass"));
        assert!(a.contains("`ina/r/ui`"));
        let wt = Worktree {
            path: "C:/w/.ina/worktrees/r-ui".into(),
            branch: "ina/r/ui".into(),
        };
        let o = orchestrator_prompt(&p, &HashMap::from([("ui".to_string(), wt)]));
        assert!(o.contains("- ui (dev)") && o.contains("branch `ina/r/ui`"));
        assert!(planner_args("hi").contains(&PLAN_SCHEMA.to_string()));
    }
}

/// Calls the real `claude` CLI (costs tokens). Run with `cargo test -- --ignored real_planner`.
#[cfg(test)]
mod real {
    #[test]
    #[ignore]
    fn real_planner() {
        let path = std::env::var_os("PATH").unwrap_or_default();
        let cwd = std::env::temp_dir();
        let args =
            super::planner_args("Build a CLI todo app in Python: 1 agent for code, 1 for tests.");
        let spec =
            crate::policy::authorize(crate::policy::Program::Claude, args, &cwd, &cwd, 0, &path)
                .unwrap();
        let plan = super::run_planner(&spec).unwrap();
        println!("{plan:#?}");
    }
}
